<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import type { AxiosInstance } from 'axios';
import type { BacktestHistoryEntry } from '@/types';
import CodeEditor from '@/components/strategyDev/CodeEditor.vue';
import PaperWorkspace from '@/components/strategyDev/PaperWorkspace.vue';
import ParameterPresets from '@/components/strategyDev/ParameterPresets.vue';
import ResearchCheckReport from '@/components/strategyDev/ResearchCheckReport.vue';
import type { ResearchCheck } from '@/utils/researchChecks';
import StrategyLibrary from '@/components/strategyDev/StrategyLibrary.vue';
import DiffViewer from '@/components/strategyDev/DiffViewer.vue';
import { libraryMatches } from '@/utils/strategyLibrary';
import type { LibraryStrategy, LibraryRun, StrategyPreset } from '@/utils/strategyLibrary';
import EquityCurveChart from '@/components/strategyDev/EquityCurveChart.vue';
import BacktestSummaryCards from '@/components/strategyDev/BacktestSummaryCards.vue';
import BacktestResultAnalysis from '@/components/ftbot/BacktestResultAnalysis.vue';
import BacktestResultComparison from '@/components/ftbot/BacktestResultComparison.vue';
import BacktestResultChart from '@/components/ftbot/BacktestResultChart.vue';
import BacktestGraphs from '@/components/ftbot/BacktestGraphs.vue';
import { useApi } from '@/composables/api';
import { useLoginInfo } from '@/composables/loginInfo';
import { useBotStore } from '@/stores/ftbotwrapper';
import { formatBacktestProfitFactor } from '@/utils/backtestMetrics';

type Item = LibraryStrategy;
type DataRow = { pair: string; timeframe: string; type: string; rows: number; start: string; end: string; duplicates: number; sorted: boolean };
type Version = { id: string; saved_at: number };
type FrozenRun = LibraryRun & { filename?:string; native_run_id?:string; artifact_sha256?:string; input_files:number; input_bytes:number; error?:string };
const router=useRouter(); const bots=useBotStore();
const items=ref<Item[]>([]), query=ref(''), selected=ref(''), tab=ref('idea');
const preset=ref<StrategyPreset>(),parameterBusy=ref(false);
const libraryOpen=ref(true), tagsText=ref(''), favorite=ref(false), versionPreview=ref('');
const tabs=[['idea','01 · Ý tưởng'],['code','02 · Mã chiến lược'],['run','03 · Backtest'],['results','04 · Kết quả'],['checks','05 · Kiểm định'],['paper','06 · Paper']];
const code=ref(''), original=ref(''), revision=ref(''), idea=ref(''), notes=ref('');
const message=ref(''), failure=ref(false), loading=ref(true), working=ref(false), api=ref<AxiosInstance>();
type CheckRun=ResearchCheck;
const checks=ref<CheckRun[]>([]), minSignals=ref(10), targetSignals=ref(20);
const checking=computed(()=>checks.value.some(c=>['pending','running'].includes(c.status)));
const versions=ref<Version[]>([]), versionId=ref(''), newOpen=ref(false), newName=ref(''), sourceName=ref('');
const data=ref<{files: DataRow[]; fee?: number; wallet?: number; stake?:number; max_open_trades?:number; pairs:string[]}>();
const start=ref('2026-09-18'), end=ref(''), wallet=ref(1000), stake=ref(100), maxTrades=ref(2), detail=ref('1m');
const interval=ref<string>(), manifestId=ref(''), resultMode=ref('summary');
const runs=ref<FrozenRun[]>([]), sourcePreview=ref(''), artifactValid=ref<boolean|null>(null);
const frozenRun=computed(()=>runs.value.find(r=>r.filename===active.value?.selectedBacktestMetadata?.filename));
const pendingArtifact=computed(()=>runs.value.some(r=>r.status==='running'));
const recentRuns=computed(()=>runs.value.filter(r=>r.strategy===selected.value).slice(0,5));
const runStatus:Record<string,string>={prepared:'Đã chuẩn bị',running:'Đang xử lý',success:'Đã lưu đầy đủ',failed:'Không hoàn tất',interrupted:'Bị gián đoạn'};
const comparisonIds=ref<string[]>([]);
const comparison=computed(()=>Object.fromEntries(Object.entries(active.value?.backtestHistory??{}).filter(([,r])=>comparisonIds.value.includes(String(r.metadata.run_id??'')))));
let poll: ReturnType<typeof setInterval>|undefined;
const selectedItem=computed(()=>items.value.find(x=>x.name===selected.value));
const filtered=computed(()=>items.value.filter(x=>libraryMatches(x,query.value)));
const dirty=computed(()=>code.value!==original.value);
const researchDirty=computed(()=>!!selected.value&&(idea.value!==(selectedItem.value?.research?.idea??'')||notes.value!==(selectedItem.value?.research?.notes??'')||tagsText.value!==(selectedItem.value?.research?.tags??[]).join(', ')||favorite.value!==!!selectedItem.value?.research?.is_favorite));
const active=computed(()=>bots.hasBots?bots.activeBot:undefined);
const results=computed(()=>active.value?.backtestHistoryList.filter(x=>x.strategy===selected.value)??[]);
const result=computed(()=>active.value?.selectedBacktestResult?.strategy_name===selected.value?active.value.selectedBacktestResult:undefined);
const running=computed(()=>active.value?.backtestRunning??false);
const realizedEquity=computed(()=>{
  if(!result.value)return [];
  let balance=result.value.starting_balance;
  const points=[{date:result.value.backtest_start,balance}];
  for(const trade of [...result.value.trades].sort((a,b)=>Date.parse(a.close_date)-Date.parse(b.close_date))){const profit=trade.profit_abs;if(typeof profit!=='number'||!Number.isFinite(profit))return [];balance+=profit;points.push({date:trade.close_date,balance});}
  return points;
});
function notify(s:string,error=false){message.value=s;failure.value=error;}
function errorMessage(e:unknown){const err=e as {response?:{data?:{detail?:unknown}},message?:string};return String(err.response?.data?.detail??err.message??e);}
async function guard(fn:()=>Promise<void>){working.value=true;try{await fn();}catch(e){notify(errorMessage(e),true);}finally{working.value=false;}}
async function loadRuns(){if(api.value)runs.value=(await api.value.get('/studio/runs')).data.runs;}
function latestResearchEntry(name:string){const frozen=runs.value.filter(r=>r.strategy===name&&r.status==='success').sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at))[0];return active.value?.backtestHistoryList.find(x=>x.strategy===name&&x.filename===frozen?.filename)??active.value?.backtestHistoryList.find(x=>x.strategy===name);}
async function refresh(){if(!api.value)return;const response=await api.value.get('/studio/library');items.value=response.data.strategies;await active.value?.getBacktestHistory();await loadRuns();}
async function select(name:string){if(parameterBusy.value){notify('Chờ thao tác tham số hoàn tất trước khi đổi chiến lược.',true);return false;}if((dirty.value||researchDirty.value)&&!window.confirm('Bỏ thay đổi mã hoặc nghiên cứu chưa lưu?'))return false;let opened=false;await guard(async()=>{
  const response=await api.value!.get('/local-strategies/'+name);selected.value=name;code.value=original.value=response.data.content;revision.value=response.data.revision;
  const meta=await api.value!.get('/studio/research/'+name);idea.value=meta.data.idea;notes.value=meta.data.notes;tagsText.value=meta.data.tags.join(', ');favorite.value=!!meta.data.is_favorite;
  versions.value=(await api.value!.get('/studio/versions/'+name)).data.versions;
  checks.value=(await api.value!.get('/studio/checks/'+name)).data.checks;
  preset.value=undefined;versionId.value='';versionPreview.value='';manifestId.value='';sourcePreview.value='';artifactValid.value=null;interval.value=selectedItem.value?.timeframe;
  const latest=latestResearchEntry(name);if(latest)await active.value?.getBacktestHistoryResult(latest);
  notify('Đang nghiên cứu '+name+'. Lưu mã không đổi bot paper đang chạy.');opened=true;
});return opened;}
async function openStrategy(name:string,nextTab='idea'){if(await select(name)){libraryOpen.value=false;tab.value=nextTab;}}
async function toggleFavorite(name:string,value:boolean){await guard(async()=>{await api.value!.put('/studio/research/'+name,{is_favorite:value});if(selected.value===name)favorite.value=value;await refresh();notify(value?'Đã đánh dấu yêu thích '+name+'.':'Đã bỏ yêu thích '+name+'.');});}
async function save(){if(!selected.value||selectedItem.value?.protected)return;await guard(async()=>{
  const response=await api.value!.put('/local-strategies/'+selected.value,{content:code.value,revision:revision.value});original.value=code.value;revision.value=response.data.revision;await refresh();versions.value=(await api.value!.get('/studio/versions/'+selected.value)).data.versions;notify('Đã lưu mã, kiểm tra cú pháp và tạo bản sao dự phòng.');
});}
async function saveResearch(){await guard(async()=>{const response=await api.value!.put('/studio/research/'+selected.value,{idea:idea.value,notes:notes.value,tags:tagsText.value.split(','),is_favorite:favorite.value});tagsText.value=response.data.tags.join(', ');await refresh();notify('Đã lưu ý tưởng, ghi chú, nhãn và yêu thích trên máy.');});}
function createDialog(copy=false){if(parameterBusy.value)return;failure.value=false;sourceName.value=copy?selected.value:'';newName.value=copy?selected.value+'Research':'';newOpen.value=true;}
async function create(){await guard(async()=>{const response=await api.value!.post('/local-strategies',{name:newName.value.trim(),source:sourceName.value||null});newOpen.value=false;await refresh();await select(response.data.name);libraryOpen.value=false;tab.value='code';notify('Đã tạo '+response.data.name+(sourceName.value?'. Đã sao chép mã; cần backtest riêng.':'. Mẫu mới chưa có tín hiệu vào lệnh.'));});}
async function compareVersion(){if(!versionId.value)return;await guard(async()=>{versionPreview.value=(await api.value!.get('/studio/versions/'+selected.value+'/'+versionId.value)).data.content;notify('Đang so sánh bản cũ với mã trong editor. Chưa khôi phục hoặc lưu mã.');});}
async function restorePreview(){if(!versionId.value)return;if(dirty.value&&!window.confirm('Thay mã chưa lưu bằng bản xem trước?'))return;await guard(async()=>{const response=await api.value!.get('/studio/versions/'+selected.value+'/'+versionId.value);code.value=response.data.content;tab.value='code';notify('Đang xem mã cũ. Nhấn Lưu nếu muốn khôi phục; bản hiện tại sẽ được sao lưu.');});}
async function copyPrompt(){const prompt=`Trong dự án FreqPilot, hãy triển khai/chỉnh sửa chiến lược ${selected.value} cho BTC/ETH Binance Futures isolated 1x, chỉ backtest và paper. Giữ engine Freqtrade 2026.9.\n\nÝ tưởng:\n${idea.value}\n\nGhi chú:\n${notes.value}\n\nĐọc mã hiện có, nêu giả định, lưu phiên bản, kiểm tra cú pháp và chạy backtest với dữ liệu funding thực. Kiểm tra lookahead/recursive nếu thay đổi indicator hoặc thời điểm tín hiệu. Không tối ưu tự động, không đổi chiến lược paper đang chạy.`;try{await navigator.clipboard.writeText(prompt);notify('Đã sao chép yêu cầu. Dán vào cuộc trò chuyện Codex này để phát triển từ ý tưởng.');}catch{notify('Trình duyệt không cho sao chép. Hãy dùng nội dung ý tưởng trong cuộc trò chuyện Codex.',true);}}
async function run(){if(!selectedItem.value||dirty.value||running.value||checking.value||parameterBusy.value)return;await guard(async()=>{
  if(preset.value&&(preset.value.revision!==revision.value||preset.value.valid===false))throw Error('Bộ tham số không khớp mã hiện tại. Chọn bộ hợp lệ trước khi chạy.');
  if(!start.value||wallet.value<=0||stake.value<=0||maxTrades.value<1)throw Error('Kiểm tra ngày, vốn, số tiền mỗi lệnh và số lệnh tối đa.');
  if(end.value&&end.value<=start.value)throw Error('Ngày kết thúc phải sau ngày bắt đầu.');
  const settings={timerange:start.value.replaceAll('-','')+'-'+end.value.replaceAll('-',''),timeframe:interval.value||selectedItem.value!.timeframe,timeframe_detail:detail.value,dry_run_wallet:wallet.value,max_open_trades:maxTrades.value,stake_amount:String(stake.value),enable_protections:false};
  const files=data.value?.files??[];for(const pair of data.value?.pairs??[]){if(!files.some(x=>x.pair===pair&&x.timeframe===settings.timeframe&&x.type==='futures'))throw Error('Chưa có nến '+settings.timeframe+' cho '+pair+'. Hãy tải dữ liệu trước.');if(!files.some(x=>x.pair===pair&&x.type==='funding_rate'))throw Error('Thiếu funding cho '+pair+'. Không chạy với funding bằng 0.');}
  // The adapter freezes inputs and delegates execution and reports to the official API.
  const response=await api.value!.post('/studio/runs',{strategy:selected.value,revision:revision.value,settings,preset_id:preset.value?.id});manifestId.value=response.data.id;
  await loadRuns();active.value!.backtestRunning=true;notify('Đã đóng băng mã và dữ liệu, bắt đầu backtest bằng engine chính thức. Hồ sơ được lưu cả khi rời trang.');
});}
async function loadResult(entry:BacktestHistoryEntry){await guard(async()=>{sourcePreview.value='';artifactValid.value=null;await active.value?.getBacktestHistoryResult(entry);tab.value='results';resultMode.value='summary';});}
async function openFrozenRun(run:FrozenRun){await active.value?.getBacktestHistory();const entry=active.value?.backtestHistoryList.find(x=>x.filename===run.filename&&x.strategy===run.strategy);if(entry)await loadResult(entry);else notify(run.error??'Kết quả chưa được lưu vào lịch sử native.',true);}
async function verifyArtifact(){if(!frozenRun.value)return;await guard(async()=>{const check=(await api.value!.get('/studio/runs/'+frozenRun.value!.id+'/verify')).data;artifactValid.value=check.valid;notify(check.valid?'Gói mã, dữ liệu và kết quả khớp dấu vân tay đã lưu.':'Gói lưu đã thay đổi hoặc thiếu tệp.',!check.valid);});}
async function previewSource(){if(!frozenRun.value)return;await guard(async()=>{sourcePreview.value=(await api.value!.get('/studio/runs/'+frozenRun.value!.id+'/source')).data.content;});}
async function downloadArtifact(){if(!frozenRun.value)return;await guard(async()=>{const id=frozenRun.value!.id;const response=await api.value!.get('/studio/runs/'+id+'/artifact',{responseType:'blob'});const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download='freqpilot-'+id+'.zip';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);notify('Đã tải gói hồ sơ; giữ riêng trên máy vì gói chứa mã chiến lược và dữ liệu.');});}
async function loadChecks(){if(api.value&&selected.value)checks.value=(await api.value.get('/studio/checks/'+selected.value)).data.checks;}
async function startCheck(kind:'lookahead'|'recursive'){if(dirty.value||running.value||checking.value||parameterBusy.value)return;await guard(async()=>{
  if(preset.value&&(preset.value.revision!==revision.value||preset.value.valid===false))throw Error('Bộ tham số không khớp mã hiện tại. Chọn lại trước khi kiểm định.');
  await api.value!.post('/studio/checks/'+selected.value+'/start',{kind,preset_id:preset.value?.id,revision:revision.value,timeframe:interval.value||selectedItem.value?.timeframe,timerange:start.value.replaceAll('-','')+'-'+end.value.replaceAll('-',''),minimum_trade_amount:minSignals.value,targeted_trade_amount:targetSignals.value});
  await loadChecks();notify('Đã gửi kiểm định cho API Freqtrade chính thức. Kết quả được lưu khi job kết thúc.');
});}
async function compareLatest(names?:string[]){await guard(async()=>{
  await active.value?.getBacktestHistory();
  await loadRuns();
  const latest=(names??items.value.map(x=>x.name)).map(latestResearchEntry).filter((x):x is BacktestHistoryEntry=>!!x);
  comparisonIds.value=latest.map(x=>x.run_id);
  for(const entry of latest)await active.value?.getBacktestHistoryResult(entry);
  libraryOpen.value=false;tab.value='compare';notify('Đã mở '+latest.length+' chiến lược để so sánh. Kiểm tra khoảng ngày và cấu hình của từng lần chạy.');
});}
function pct(n:number|undefined){return n==null?'—':(n*100).toFixed(2)+'%';}
function fmtDate(value:string){return value?.slice(0,16).replace('T',' ')+' UTC';}
async function pollBacktest(){if(!active.value)return;try{const was=active.value.backtestRunning;await active.value.pollBacktest();if(was&&!active.value.backtestRunning){await refresh();tab.value='results';notify('Backtest đã kết thúc. Xem số lệnh, phí và rủi ro trước khi đánh giá.');}}catch{/* Native API can be idle or still initializing. */}}
async function initialize(){try{
  await Promise.all(bots.allBotStores.map(b=>b.getState().catch(()=>null)));
  const server=bots.allBotStores.find(b=>b.isWebserverMode);if(!server)throw Error('Cần kết nối dịch vụ Backtest 8091 trong Settings → Bots.');
  bots.selectBot(server.botId);api.value=useApi(useLoginInfo(server.botId),server.botId).api;
  data.value=(await api.value.get('/studio/data')).data;wallet.value=data.value?.wallet??1000;stake.value=Number(data.value?.stake??100);maxTrades.value=data.value?.max_open_trades??2;
  await refresh();await pollBacktest();if(items.value[0])await select(items.value.find(x=>x.name==='StarterFuturesResearch')?.name??items.value[0].name);
  poll=setInterval(()=>{if(running.value)void pollBacktest();if(checking.value)void loadChecks().catch(e=>notify(errorMessage(e),true));if(pendingArtifact.value)void loadRuns().then(async()=>{if(!pendingArtifact.value)await active.value?.getBacktestHistory();}).catch(e=>notify(errorMessage(e),true));},1500);
}catch(e){notify(errorMessage(e),true);}finally{loading.value=false;}}
onMounted(initialize);onUnmounted(()=>{if(poll)clearInterval(poll);});
</script>

<template>
  <div class="pilot">
    <div class="pilot-heading" :class="{'library-mode':libraryOpen}"><div><span class="eyebrow">FREQPILOT · RESEARCH WORKSPACE</span><h1>Từ ý tưởng đến chiến lược có bằng chứng</h1><p>Binance Futures · BTC / ETH · Freqtrade 2026.9</p></div><div class="row"><button v-if="api&&!libraryOpen" @click="libraryOpen=true">← Thư viện chiến lược</button><button v-if="api" :disabled="working||running" @click="compareLatest()">So sánh kết quả thư viện</button><div class="safe">● Chỉ backtest & paper</div></div></div>
    <div v-if="message&&(!libraryOpen||failure)" class="feedback" :class="{bad:failure}" role="status">{{message}}</div>
    <div v-if="loading" class="empty">Đang kết nối dữ liệu và chiến lược…</div>
    <div v-else-if="!api" class="empty"><h2>Kết nối bộ cài hiện tại</h2><p>Thêm Backtest tại http://localhost:8091 bằng tài khoản local sẵn có.</p><button @click="router.push('/settings')">Mở cài đặt kết nối</button></div>
    <StrategyLibrary v-else-if="libraryOpen" :items="items" :runs="runs" :busy="working" @open="openStrategy" @favorite="toggleFavorite" @create="createDialog()" @compare="compareLatest" @refresh="guard(refresh)" />
    <div v-else class="workspace">
      <aside><div class="row"><h2>Chiến lược <small>{{items.length}}</small></h2><button aria-label="Tải lại thư viện" @click="guard(refresh)">↻</button></div><button class="primary wide" @click="createDialog()">＋ Tạo chiến lược</button><input v-model="query" aria-label="Tìm chiến lược" placeholder="Tên, mô tả hoặc nhãn…"><div class="library"><button v-for="item in filtered" :key="item.name" class="strategy" :class="{chosen:selected===item.name}" @click="openStrategy(item.name)"><b>{{item.research?.is_favorite?'★ ':''}}{{item.name}}</b><span>{{item.timeframe??'Kiểm tra mã'}} · {{item.can_short==null?'Chưa rõ chiều':item.can_short?'Hỗ trợ short':'Không khai báo short'}} <span v-if="item.protected">· Paper 🔒</span></span><small>{{item.research?.idea?.slice(0,65)||'Chưa có mô tả nghiên cứu'}}</small></button></div><a href="http://localhost:8092/tools/strategy-dev" target="_blank" rel="noopener">Mở Ultimate để so sánh ↗</a><small class="lineage">Kế thừa FreqUI Ultimate + API chính thức của Freqtrade.</small></aside>
      <section v-if="selected"><div class="strategy-head"><div><span class="eyebrow">CHIẾN LƯỢC ĐANG NGHIÊN CỨU</span><h2>{{selected}}</h2><small>Mã {{revision.slice(0,10)}} · {{selectedItem?.timeframe}} · Binance USDT-M</small></div><button @click="createDialog(true)">Sao chép để thử</button></div>
        <nav class="steps" aria-label="Quy trình phát triển"><button v-for="[id,label] in tabs" :key="id" :class="{active:tab===id}" @click="tab=id!">{{label}}</button></nav>
        <div v-if="tab==='idea'" class="pane"><h3>Viết rõ quy tắc trước khi thử</h3><p>Điều kiện vào/ra, cắt lỗ, chốt lời, khung thời gian và rủi ro mỗi lệnh.</p><label>Ý tưởng chiến lược<textarea v-model="idea" rows="7" placeholder="Ví dụ: short khi giá hồi về vùng Fibo sau một đợt tăng…" /></label><label>Ghi chú và điều cần kiểm chứng<textarea v-model="notes" rows="4" placeholder="Giả định, trường hợp bỏ lệnh, điều đã thử…" /></label><label>Nhãn (phân cách bằng dấu phẩy)<input v-model="tagsText" placeholder="fibonacci, short, reversal" maxlength="400"></label><label class="favorite-field"><input v-model="favorite" type="checkbox"> Đánh dấu yêu thích</label><div class="row"><button class="primary" :disabled="working" @click="saveResearch">Lưu nghiên cứu</button><button @click="copyPrompt">Sao chép yêu cầu cho Codex</button><button @click="tab='code'">Tiếp: xem mã →</button></div><p class="muted">Dùng Codex đang kết nối với dự án để phát triển từ ý tưởng. FreqPilot chưa có chatbot AI riêng.</p></div>
        <div v-else-if="tab==='code'" class="pane"><div class="row"><b>{{selected}}.py <span v-if="dirty">● Chưa lưu</span></b><span class="spacer"/><button :disabled="working||!dirty||selectedItem?.protected" class="primary" @click="save">Lưu mã</button><button @click="select(selected)">Tải lại</button></div><p v-if="selectedItem?.protected" class="hint">Mã paper đang chạy được bảo vệ. Hãy sao chép trước khi sửa.</p><div class="editor"><CodeEditor v-model="code" language="python" :readonly="selectedItem?.protected" :filename="selected+'.py'" @save="save" /></div><div class="row"><label>Phiên bản trước<select v-model="versionId"><option value="">Chọn bản sao dự phòng</option><option v-for="v in versions" :key="v.id" :value="v.id">{{new Date(v.saved_at*1000).toLocaleString('vi-VN')}}</option></select></label><button :disabled="!versionId||working" @click="compareVersion">So sánh phiên bản</button><button :disabled="!versionId||working" @click="restorePreview">Nạp bản cũ vào editor</button><span class="spacer"/><button :disabled="dirty" @click="tab='run'">Tiếp: backtest →</button></div><div v-if="versionPreview" class="version-diff"><div class="row"><h3>So sánh mã · chỉ đọc</h3><button @click="versionPreview=''">Đóng so sánh</button></div><p>So sánh theo dòng bằng bộ xem có sẵn của Ultimate. Chưa khôi phục hoặc lưu mã.</p><DiffViewer :saved="versionPreview" :current="code" :has-changes="versionPreview!==code" :saved-label="'Bản sao ' + versionId" current-label="Mã trong editor" /></div></div>
        <div v-else-if="tab==='run'" class="pane"><h3>Backtest với dữ liệu đang có</h3><ParameterPresets v-if="api" :key="selected" :api="api" :strategy="selected" :revision="revision" :busy="working||running||checking" :selected="preset" @selected="preset=$event" @busy="parameterBusy=$event" /><p>Mô phỏng nến với chi tiết 1m; chưa phải khớp lệnh tick/L2. Phí hiện tại: {{pct(data?.fee)}} mỗi chiều.</p><div class="form-grid"><label>Từ ngày<input v-model="start" type="date"></label><label>Đến ngày (không gồm ngày này)<input v-model="end" type="date"></label><label>Khung tín hiệu<select v-model="interval"><option v-for="tf in [...new Set(data?.files.filter(x=>x.type==='futures').map(x=>x.timeframe))]" :key="tf">{{tf}}</option></select></label><label>Khung chi tiết<select v-model="detail"><option>1m</option></select></label><label>Vốn mô phỏng (USDT)<input v-model.number="wallet" type="number" min="1"></label><label>Số tiền mỗi lệnh<input v-model.number="stake" type="number" min="1"></label><label>Lệnh mở tối đa<input v-model.number="maxTrades" type="number" min="1" max="10"></label></div><div class="hint">BTC / ETH · isolated · chiến lược mẫu 1x · cache tắt · có mark price và funding.</div><div class="row"><button class="primary" :disabled="working||dirty||running||checking||parameterBusy" @click="run">{{running?'Đang backtest…':'Chạy backtest'}}</button><span v-if="dirty">Lưu mã trước khi chạy.</span><span v-if="manifestId">Hồ sơ chạy: {{manifestId.slice(0,10)}}</span></div><div v-if="running" class="progress"><progress :value="active?.backtestProgress??0" max="1"/><span>{{active?.backtestStep}} · {{Math.round((active?.backtestProgress??0)*100)}}%</span></div><div v-if="recentRuns.length" class="artifact-panel"><h3>Hồ sơ gần đây</h3><article v-for="item in recentRuns" :key="item.id" class="check-card"><div class="row"><b>{{runStatus[item.status]??item.status}}</b><small>{{new Date(item.created_at).toLocaleString('vi-VN')}} · mã {{item.revision.slice(0,10)}}</small><button v-if="item.status==='success'" @click="openFrozenRun(item)">Mở kết quả & hồ sơ</button></div><p v-if="item.preset">Bộ tham số: {{item.preset.label}} · {{item.preset.native_sha256.slice(0,10)}}</p><p>{{item.settings.timeframe}} · {{item.settings.timerange}} · {{item.input_files}} tệp đầu vào</p><p v-if="item.error" class="feedback bad">{{item.error}}</p></article></div><details><summary>Phạm vi dữ liệu trên máy</summary><table><thead><tr><th>Cặp</th><th>Dữ liệu</th><th>Khung</th><th>Bản ghi</th><th>Từ UTC</th><th>Đến UTC</th></tr></thead><tbody><tr v-for="f in data?.files" :key="f.pair+f.type+f.timeframe"><td>{{f.pair}}</td><td>{{f.type}}</td><td>{{f.timeframe}}</td><td>{{f.rows}}</td><td>{{fmtDate(f.start)}}</td><td>{{fmtDate(f.end)}}</td></tr></tbody></table><small>Đây là kiểm tra dữ liệu local, không phải một lần đối chiếu mới với Binance.</small></details></div>
        <div v-else-if="tab==='results'" class="pane"><div class="row"><h3>Lịch sử của {{selected}}</h3><button @click="guard(refresh)">Tải lại kết quả</button></div><div v-if="!results.length" class="empty">Chưa có kết quả. Chạy backtest trước khi đánh giá.</div><div v-else class="history"><button v-for="entry in results" :key="entry.run_id+entry.filename" @click="loadResult(entry)"><b>{{new Date(entry.backtest_start_time*1000).toLocaleString('vi-VN')}}</b><small>{{entry.timeframe}} · {{entry.filename}}</small></button></div><template v-if="result"><div v-if="frozenRun" class="artifact-panel"><div class="row"><b>Hồ sơ chạy {{frozenRun.id.slice(0,10)}}</b><span class="safe">{{frozenRun.status==='success'?'Đã lưu gói đầu vào & kết quả':frozenRun.status}}</span></div><details v-if="frozenRun.preset"><summary>Giá trị tham số của lần chạy</summary><pre class="source-preview">{{JSON.stringify(frozenRun.preset.values,null,2)}}</pre></details><p v-if="frozenRun.preset">Bộ tham số đã chạy: <b>{{frozenRun.preset.label}}</b> · dấu vân tay {{frozenRun.preset.native_sha256.slice(0,10)}}. Hồ sơ paper dùng bản này.</p><p>Mã {{frozenRun.revision.slice(0,10)}} · {{frozenRun.input_files}} tệp đầu vào · {{(frozenRun.input_bytes/1048576).toFixed(2)}} MB. Engine đã chạy trên bản sao riêng của mã và dữ liệu.</p><p v-if="frozenRun.revision!==revision" class="hint">Mã hiện tại khác phiên bản trong kết quả này. Mở mã đã chạy để đối chiếu.</p><div class="row"><button :disabled="working||frozenRun.status!=='success'" @click="verifyArtifact">Kiểm tra tính toàn vẹn</button><button :disabled="working" @click="previewSource">Xem mã đã chạy</button><button :disabled="working||frozenRun.status!=='success'" @click="downloadArtifact">Tải gói mã + dữ liệu + kết quả</button></div><p v-if="artifactValid!==null" :class="{bad:!artifactValid}" class="feedback">{{artifactValid?'Dấu vân tay gói lưu khớp. Đây không phải chứng nhận chất lượng chiến lược.':'Gói lưu không khớp dấu vân tay.'}}</p><details v-if="sourcePreview" open><summary>Mã gốc của lần chạy · chỉ đọc</summary><pre class="source-preview">{{sourcePreview}}</pre></details><small>Gói lưu gồm mã local, nến/mark/funding, cấu hình nghiên cứu và ZIP gốc. Thư viện bên ngoài được cố định qua image engine; dữ liệu thị trường lấy qua mạng không nằm trong gói này.</small></div><div v-else class="hint">Báo cáo cũ chưa có gói mã và dữ liệu đầy đủ. Mã đang mở có thể khác mã của báo cáo; hãy chạy lại để tạo hồ sơ có thể kiểm tra.</div><div class="row modes"><button v-for="[mode,label] in [['summary','Tổng quan'],['analysis','Chỉ số & giao dịch'],['chart','Biểu đồ lệnh'],['graphs','Phân phối'],['compare','So sánh đã mở']]" :key="mode" :class="{active:resultMode===mode}" @click="resultMode=mode!">{{label}}</button></div><div class="core-metrics"><div><small>Lãi / lỗ ròng</small><b>{{result.profit_total_abs.toFixed(2)}} USDT</b><span>{{pct(result.profit_total)}}</span></div><div><small>Drawdown tối đa</small><b>{{pct(result.max_drawdown_account)}}</b></div><div><small>Số lệnh</small><b>{{result.total_trades}}</b></div><div><small>Profit factor</small><b>{{formatBacktestProfitFactor(result)}}</b></div></div><BacktestSummaryCards :summary="result as unknown as Record<string,unknown>"/><div v-if="result.total_trades<30" class="hint">Chỉ có {{result.total_trades}} lệnh: mẫu nhỏ, chưa đủ để kết luận chất lượng.</div><div v-if="resultMode==='summary'" class="equity-summary"><h3>Vốn theo các lệnh đã đóng</h3><EquityCurveChart :equity="realizedEquity" :starting-balance="result.starting_balance"/><small>Đã cộng lãi/lỗ ròng của lệnh đóng; không phải đường vốn gồm vị thế đang mở. Mã hiện tại có thể khác bản đã dùng trong báo cáo cũ.</small></div><div class="legacy-report"><BacktestResultAnalysis v-if="resultMode==='analysis'" :backtest-result="result"/><BacktestResultChart v-else-if="resultMode==='chart'" :timeframe="result.timeframe" :strategy="selected" :timerange="result.timerange" :backtest-result="result"/><BacktestGraphs v-else-if="resultMode==='graphs'" :trades="result.trades"/><BacktestResultComparison v-else-if="resultMode==='compare'&&active" :backtest-results="active.backtestHistory"/></div></template></div>
        <div v-else-if="tab==='checks'" class="pane"><h3>Kiểm định trước khi chuyển sang paper</h3><ParameterPresets v-if="api" :key="selected" :api="api" :strategy="selected" :revision="revision" :busy="working||running||checking" :selected="preset" @selected="preset=$event" @busy="parameterBusy=$event" /><p>Dùng API lookahead / recursive có sẵn của Freqtrade 2026.9. Khoảng ngày và khung tín hiệu lấy từ tab Backtest. Không tối ưu tham số.</p><div class="row"><button class="primary" :disabled="working||dirty||running||checking||parameterBusy" @click="startCheck('lookahead')">Kiểm tra lookahead</button><button :disabled="working||dirty||running||checking||parameterBusy" @click="startCheck('recursive')">Kiểm tra warmup / recursive</button><button @click="guard(loadChecks)">Tải lại kiểm định</button></div><details><summary>Tham số chẩn đoán</summary><div class="form-grid"><label>Số tín hiệu tối thiểu<input v-model.number="minSignals" type="number" min="1" max="500"></label><label>Số tín hiệu muốn kiểm tra<input v-model.number="targetSignals" type="number" min="1" max="200"></label></div></details><div class="hint">Không phát hiện bias trên một mẫu nhỏ không chứng minh chiến lược an toàn hay có lợi nhuận. Recursive chỉ kiểm tra cặp đầu tiên theo cơ chế gốc của Freqtrade.</div><div v-if="!checks.length" class="empty">Chưa có kiểm định cho chiến lược này.</div><ResearchCheckReport
            v-for="check in checks"
            :key="check.id"
            :check="check"
            :context="{
              strategy: selected,
              revision,
              parameterRevision: preset?.native_sha256 ?? selectedItem?.parameter_revision,
              timeframe: interval,
              timerange: start.replaceAll('-', '') + '-' + end.replaceAll('-', ''),
            }"
          /></div>
        <div v-else-if="tab==='compare'" class="pane"><h3>So sánh chiến lược đã chạy</h3><p>Mỗi cột là một lần chạy đã lưu. Các chiến lược có thể dùng khung thời gian khác nhau; hãy đọc cấu hình trước khi xếp hạng.</p><div class="hint">Lợi nhuận cao với ít lệnh chưa chứng minh chất lượng. Xem drawdown, profit factor, số lệnh và kiểm định lookahead / recursive.</div><div class="legacy-report"><BacktestResultComparison :backtest-results="comparison"/></div></div>
        <div v-else class="pane"><PaperWorkspace v-if="api" :api="api" :strategy="selected" :revision="revision" :run="frozenRun?.strategy===selected?frozenRun:undefined" @open-results="tab='results'" /></div>
      </section><div v-else class="empty">Tạo hoặc chọn một chiến lược để bắt đầu.</div>
    </div>
    <div v-if="newOpen" class="modal" role="dialog" aria-modal="true" aria-label="Tạo chiến lược FreqPilot"><form @submit.prevent="create"><h2>{{sourceName?'Sao chép chiến lược':'Tạo chiến lược mới'}}</h2><p v-if="failure" class="feedback bad">{{message}}</p><p>Đặt tên tệp và class, ví dụ MyBreakoutFutures.</p><label>Tên chiến lược<input v-model="newName" required pattern="[A-Za-z][A-Za-z0-9_]{0,79}" maxlength="80" autofocus></label><label>Bắt đầu từ<select v-model="sourceName"><option value="">Mẫu trống · chưa có tín hiệu</option><option v-for="item in items" :key="item.name">{{item.name}}</option></select></label><div class="row"><button type="button" @click="newOpen=false">Hủy</button><button class="primary" :disabled="working">Tạo và mở mã</button></div></form></div>
  </div>
</template>

